const blessed = require('blessed');
const screen = blessed.screen({ smartCSR: true, title: 'tui' });

const box = blessed.box({
  top: 'center', left: 'center', width: '50%', height: '50%',
  content: '{{box_content}}',
  border: { type: 'line' },
  style: { border: { fg: 'cyan' } }
});

screen.append(box);
screen.key(['q', 'C-c'], () => process.exit(0));
screen.render();
